// Signs in to the local dev app with a local magic-link token hash, then
// captures six app screens at a 390x844 viewport through Chrome DevTools.
import { readFileSync, writeFileSync } from "node:fs";

const [, , port, tokenFile, outDir] = process.argv;
const tokenHash = readFileSync(tokenFile, "utf8").trim();
const base = "http://localhost:5173";

let targets;
for (let i = 0; i < 50; i++) {
  try {
    targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    if (targets.some((t) => t.type === "page")) break;
  } catch {}
  await new Promise((r) => setTimeout(r, 200));
}
const page = targets.find((t) => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r, { once: true }));
let id = 0;
const pending = new Map();
ws.addEventListener("message", (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve) => {
    const n = ++id;
    pending.set(n, resolve);
    ws.send(JSON.stringify({ id: n, method, params }));
  });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

await send("Page.enable");
await send("Emulation.setDeviceMetricsOverride", {
  width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
});
await send("Emulation.setEmulatedMedia", {
  features: [{ name: "prefers-color-scheme", value: "light" }],
});

async function go(url, wait = 3500) {
  await send("Page.navigate", { url });
  await sleep(wait);
  const r = await send("Runtime.evaluate", { expression: "location.pathname", returnByValue: true });
  return r.result?.result?.value;
}

const landed = await go(`${base}/login/callback?token_hash=${encodeURIComponent(tokenHash)}&type=magiclink`, 5000);
console.log("after callback:", landed);

const screens = [
  ["today", "/app"],
  ["items", "/app/items"],
  ["history", "/app/history"],
  ["timeline", "/app/timeline"],
  ["patterns", "/app/patterns"],
  ["settings", "/app/settings"],
];
for (const [name, path] of screens) {
  const at = await go(`${base}${path}`);
  const shot = await send("Page.captureScreenshot", { format: "png" });
  writeFileSync(`${outDir}/${name}.png`, Buffer.from(shot.result.data, "base64"));
  console.log(name, "at", at);
}
ws.close();
process.exit(0);

